public class ShortPackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("pack(0, 0)", 0, ShortPacker.pack(0, 0));
        check("pack(1, 0)", 65536, ShortPacker.pack(1, 0));
        check("pack(0xABCD, 0x1234)", 0xABCD1234, ShortPacker.pack(0xABCD, 0x1234));
        check("high(0xABCD1234)", 0xABCD, ShortPacker.high(0xABCD1234));
        check("low(0xABCD1234)", 0x1234, ShortPacker.low(0xABCD1234));
        check("high(-1)", 65535, ShortPacker.high(-1));
        check("low(-1)", 65535, ShortPacker.low(-1));
        int original = -2000000000;
        check("round trip", original,
                ShortPacker.pack(ShortPacker.high(original), ShortPacker.low(original)));

        boolean threwHigh = false;
        try {
            ShortPacker.pack(70000, 0);
        } catch (IllegalArgumentException e) {
            threwHigh = true;
        } catch (RuntimeException e) {
            threwHigh = false;
        }
        check("pack(70000, 0) throws", true, threwHigh);

        boolean threwLow = false;
        try {
            ShortPacker.pack(0, -1);
        } catch (IllegalArgumentException e) {
            threwLow = true;
        } catch (RuntimeException e) {
            threwLow = false;
        }
        check("pack(0, -1) throws", true, threwLow);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

