public class ShortPacker {

    public static int pack(int high, int low) {
        if (high < 0 || high > 65535 || low < 0 || low > 65535) {
            throw new IllegalArgumentException("half out of range");
        }
        return (high << 16) | low;
    }

    public static int high(int packed) {
        return (packed >>> 16) & 0xFFFF;
    }

    public static int low(int packed) {
        return packed & 0xFFFF;
    }
}
